describe('Password Strength Indicator', () => {
  beforeEach(() => {
    cy.visit('/auth/password-reset');
  });

  it('should display password strength indicator as password is typed', () => {
    // Intercept the password strength API call
    cy.intercept('POST', '/api/password/strength').as('checkStrength');

    // Get the password input field
    cy.get('[data-testid="password-input"]').should('be.visible');

    // Type a weak password
    cy.get('[data-testid="password-input"]').type('password123');

    // Wait for the strength check API call
    cy.wait('@checkStrength');

    // Verify the strength indicator shows 'Weak'
    cy.get('[data-testid="strength-indicator"]').should('be.visible');
    cy.get('[data-testid="strength-indicator"]').should('contain', 'Weak');
    cy.get('[data-testid="strength-level"]').should('have.class', 'level-weak');

    // Type a stronger password
    cy.get('[data-testid="password-input"]').clear().type('Password123!');

    // Wait for the strength check API call
    cy.wait('@checkStrength');

    // Verify the strength indicator updates to 'Strong'
    cy.get('[data-testid="strength-indicator"]').should('contain', 'Strong');
    cy.get('[data-testid="strength-level"]').should('have.class', 'level-strong');
  });

  it('should handle empty password input and display appropriate message', () => {
    // Verify password input is empty initially
    cy.get('[data-testid="password-input"]').should('have.value', '');

    // Verify strength indicator is not visible or shows default state
    cy.get('[data-testid="strength-indicator"]').should('not.exist');

    // Clear any existing text
    cy.get('[data-testid="password-input"]').clear();

    // Verify no strength check API call is made
    cy.intercept('POST', '/api/password/strength').as('checkStrength');

    // Attempt to submit the form without a password
    cy.get('[data-testid="submit-button"]').click();

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Password is required');

    // Verify strength indicator remains hidden
    cy.get('[data-testid="strength-indicator"]').should('not.exist');
  });
});
